#!/usr/bin/env python3
"""A small, original reimplementation of the observed gron CLI behavior."""
import collections
import gzip
import json
import math
import os
import re
import ssl
import sys
import unicodedata
import urllib.error
import urllib.request
from decimal import Decimal, InvalidOperation

VERSION = "dev"

USAGE = """Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0\tOK
  1\tFailed to open file
  2\tFailed to read input
  3\tFailed to form statements
  4\tFailed to fetch URL
  5\tFailed to parse statements
  6\tFailed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
"""

# JavaScript words that the original avoids for dot notation.  (Future-ish words
# like let/await are intentionally not all excluded: this mirrors observation.)
RESERVED = {
    "break", "case", "catch", "class", "const", "continue", "debugger",
    "default", "delete", "do", "else", "export", "extends", "false",
    "finally", "for", "function", "if", "import", "in", "instanceof",
    "new", "null", "return", "super", "switch", "this", "throw", "true",
    "try", "typeof", "var", "void", "while", "with", "yield",
}

MISSING = object()

class JsonNumber:
    __slots__ = ("raw",)
    def __init__(self, raw):
        self.raw = str(raw)
    def __repr__(self):
        return f"JsonNumber({self.raw!r})"

class JSStreamNumber:
    __slots__ = ("raw", "value")
    def __init__(self, raw):
        self.raw = str(raw)
        try:
            self.value = float(raw)
        except Exception:
            self.value = math.inf
    def __repr__(self):
        return f"JSStreamNumber({self.raw!r})"

class Options:
    def __init__(self):
        self.ungron = False
        self.values = False
        self.colorize = False
        self.monochrome = False
        self.stream = False
        self.insecure = False
        self.json = False
        self.no_sort = False
        self.version = False
        self.help = False
        self.proxy = ""
        self.noproxy = ""
        self.args = []


def eprint(s=""):
    sys.stderr.write(str(s) + "\n")


def go_flag_name(token):
    if token.startswith("--"):
        return token[2:]
    if token.startswith("-"):
        return token[1:]
    return token


def parse_bool_literal(val):
    v = val.lower()
    if v in ("1", "t", "true"):
        return True
    if v in ("0", "f", "false"):
        return False
    raise ValueError


def parse_args(argv):
    opts = Options()
    bool_flags = {
        "u": "ungron", "ungron": "ungron",
        "v": "values", "values": "values",
        "c": "colorize", "colorize": "colorize",
        "m": "monochrome", "monochrome": "monochrome",
        "s": "stream", "stream": "stream",
        "k": "insecure", "insecure": "insecure",
        "j": "json", "json": "json",
        "no-sort": "no_sort",
        "version": "version",
        "h": "help", "help": "help",
    }
    str_flags = {"x": "proxy", "proxy": "proxy", "noproxy": "noproxy"}

    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            opts.args = argv[i+1:]
            break
        if tok == "-" or not tok.startswith("-"):
            opts.args = argv[i:]
            break

        raw = go_flag_name(tok)
        if "=" in raw:
            name, val = raw.split("=", 1)
            has_val = True
        else:
            name, val = raw, None
            has_val = False

        if name in bool_flags:
            attr = bool_flags[name]
            if has_val:
                try:
                    setattr(opts, attr, parse_bool_literal(val))
                except ValueError:
                    eprint(f"invalid boolean value {val!r} for -{name}")
                    sys.stderr.write(USAGE)
                    raise SystemExit(2)
            else:
                setattr(opts, attr, True)
            i += 1
            continue

        if name in str_flags:
            attr = str_flags[name]
            if has_val:
                setattr(opts, attr, val)
                i += 1
                continue
            if i + 1 >= len(argv):
                eprint(f"flag needs an argument: -{name}")
                sys.stderr.write(USAGE)
                raise SystemExit(2)
            setattr(opts, attr, argv[i+1])
            i += 2
            continue

        eprint(f"flag provided but not defined: -{name}")
        sys.stderr.write(USAGE)
        raise SystemExit(2)

    return opts


def quote_json_string(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif o < 0x20 or o in (0x2028, 0x2029) or 0xD800 <= o <= 0xDFFF:
            out.append('\\u%04x' % o)
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)


def is_ident_start(ch):
    if ch in ('_', '$'):
        return True
    cat = unicodedata.category(ch)
    return cat[0] == 'L' or cat == 'Nl'


def is_ident_part(ch):
    if is_ident_start(ch):
        return True
    cat = unicodedata.category(ch)
    return cat[0] == 'M' or cat == 'Nd' or cat == 'Pc' or ch in ('\u200c', '\u200d')


def can_dot_identifier(s):
    if not s or s in RESERVED:
        return False
    if not is_ident_start(s[0]):
        return False
    return all(is_ident_part(c) for c in s[1:])


def path_to_string(path, root="json"):
    s = root
    for p in path:
        if isinstance(p, int):
            s += f"[{p}]"
        else:
            if can_dot_identifier(p):
                s += "." + p
            else:
                s += "[" + quote_json_string(p) + "]"
    return s


def compact_json(v, sort_keys=False):
    if v is MISSING:
        return "null"
    if isinstance(v, JsonNumber):
        return v.raw
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, str):
        return quote_json_string(v)
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        return go_float_format(v)
    if isinstance(v, (list, tuple)):
        return "[" + ",".join(compact_json(x, sort_keys=sort_keys) for x in v) + "]"
    if isinstance(v, dict):
        keys = list(v.keys())
        if sort_keys:
            keys.sort()
        return "{" + ",".join(quote_json_string(str(k)) + ":" + compact_json(v[k], sort_keys=sort_keys) for k in keys) + "}"
    return quote_json_string(str(v))


def pretty_json(v, indent=0):
    if v is MISSING:
        return "null"
    if isinstance(v, dict):
        if not v:
            return "{}"
        keys = sorted(v.keys())
        inner = []
        pad_child = " " * (indent + 2)
        for k in keys:
            inner.append(pad_child + quote_json_string(str(k)) + ": " + pretty_json(v[k], indent + 2))
        return "{\n" + ",\n".join(inner) + "\n" + " " * indent + "}"
    if isinstance(v, list):
        if not v:
            return "[]"
        pad_child = " " * (indent + 2)
        inner = [pad_child + pretty_json(x, indent + 2) for x in v]
        return "[\n" + ",\n".join(inner) + "\n" + " " * indent + "]"
    return compact_json(v)


def go_float_format_from_raw(raw):
    raw_s = str(raw)
    try:
        f = float(raw_s)
    except Exception:
        return raw_s
    # encoding/json preserves negative zero when decoding into float64.
    if f == 0.0 and raw_s.lstrip().startswith('-'):
        return "-0"
    return go_float_format(f)


def normalize_exp(s):
    def repl(m):
        sign = m.group(1)
        digits = m.group(2).lstrip('0') or '0'
        return 'e' + sign + digits
    return re.sub(r'e([+-])([0-9]+)', repl, s)


def fixed_from_repr(rep):
    try:
        d = Decimal(rep)
        s = format(d, 'f')
    except (InvalidOperation, ValueError):
        s = rep
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == '-0':
        # The caller handles true negative zero; avoid creating it by stripping.
        s = '0'
    return s


def go_float_format(f):
    if math.isnan(f) or math.isinf(f):
        # JSON cannot represent these, but keep a harmless spelling.
        return "null"
    if f == 0.0:
        return "0"
    af = abs(f)
    rep = repr(f)
    rep = rep.replace('E', 'e')
    if 1e-6 <= af < 1e21:
        return fixed_from_repr(rep)
    if 'e' not in rep:
        # Build an exponential form if repr chose fixed outside Go's JSON range.
        rep = format(f, '.15e')
        mant, exp = rep.split('e')
        mant = mant.rstrip('0').rstrip('.')
        rep = mant + 'e' + ('+' if int(exp) >= 0 else '-') + str(abs(int(exp)))
    return normalize_exp(rep)


def object_pairs_hook(pairs):
    d = collections.OrderedDict()
    for k, v in pairs:
        d[k] = v
    return d


def decode_first_json(text):
    dec = json.JSONDecoder(object_pairs_hook=object_pairs_hook,
                           parse_int=lambda s: JsonNumber(s),
                           parse_float=lambda s: JsonNumber(s))
    # raw_decode tolerates trailing garbage just like the observed tool.
    idx = 0
    n = len(text)
    while idx < n and text[idx] in ' \t\r\n':
        idx += 1
    if idx >= n:
        raise ValueError("EOF")
    try:
        val, _ = dec.raw_decode(text, idx)
        return val
    except json.JSONDecodeError as e:
        raise ValueError(go_json_error(text, e))


def go_json_error(text, err):
    pos = err.pos
    ch = text[pos] if pos < len(text) else ''
    # Some common encodings of Go's encoding/json errors.
    if pos >= len(text) or err.msg.startswith('Expecting value') and not ch:
        return "EOF"
    if text[pos:pos+1] == 'n' and text[pos:pos+4] != 'null':
        got = text[pos+1:pos+2] or ' '
        return f"invalid character {got!r} in literal null (expecting 'u')"
    if text[pos:pos+1] == 't' and text[pos:pos+4] != 'true':
        got = text[pos+1:pos+2] or ' '
        return f"invalid character {got!r} in literal true (expecting 'r')"
    if text[pos:pos+1] == 'f' and text[pos:pos+5] != 'false':
        got = text[pos+1:pos+2] or ' '
        return f"invalid character {got!r} in literal false (expecting 'a')"
    if err.msg.startswith('Expecting property name'):
        return f"invalid character {ch!r} looking for beginning of object key string"
    if err.msg.startswith('Expecting value'):
        return f"invalid character {ch!r} looking for beginning of value"
    if err.msg.startswith("Expecting ':' delimiter"):
        return f"invalid character {ch!r} after object key"
    if err.msg.startswith("Expecting ',' delimiter"):
        return f"invalid character {ch!r} after object key:value pair"
    if err.msg.startswith('Unterminated string'):
        return "unexpected end of JSON input"
    return err.msg


class Statement:
    __slots__ = ("path", "value")
    def __init__(self, path, value):
        self.path = list(path)
        self.value = value
    def lhs(self):
        return path_to_string(self.path)
    def line(self):
        return f"{self.lhs()} = {compact_json(self.value)};"
    def jline(self):
        return compact_json([self.path, self.value])


def container_marker(v):
    if isinstance(v, dict):
        return collections.OrderedDict()
    if isinstance(v, list):
        return []
    return v


def form_statements(v, prefix=None, sort=True):
    if prefix is None:
        prefix = []
    out = []
    def walk(val, path):
        if isinstance(val, dict):
            out.append(Statement(path, collections.OrderedDict()))
            items = list(val.items())
            for k, subv in items:
                walk(subv, path + [k])
        elif isinstance(val, list):
            out.append(Statement(path, []))
            for i, subv in enumerate(val):
                walk(subv, path + [i])
        else:
            out.append(Statement(path, val))
    walk(v, list(prefix))
    if sort:
        out.sort(key=lambda st: st.line())
    return out

# ANSI colors observed from the original.
C_RESET = "\033[0m"
C_RESET_BOLD = "\033[0;22m"
C_BLUE_BOLD = "\033[34;1m"
C_MAGENTA = "\033[35m"
C_YELLOW = "\033[33m"
C_RED = "\033[31m"
C_CYAN = "\033[36m"
C_GREEN = "\033[32m"
C_BOLD = "\033[1m"
C_UNBOLD = "\033[22m"


def c_ident(s):
    return C_BLUE_BOLD + s + C_RESET_BOLD


def c_value(v):
    if isinstance(v, JsonNumber) or (isinstance(v, (int, float)) and not isinstance(v, bool)):
        return C_RED + compact_json(v) + C_RESET
    if v is None or v is True or v is False:
        return C_CYAN + compact_json(v) + C_RESET
    if isinstance(v, str):
        return C_YELLOW + quote_json_string(v) + C_RESET
    if isinstance(v, dict):
        if not v:
            return C_MAGENTA + "{}" + C_RESET
        keys = sorted(v.keys())
        return C_MAGENTA + "{" + C_RESET + ",".join(c_value(str(k)) + ":" + c_value(v[k]) for k in keys) + C_MAGENTA + "}" + C_RESET
    if isinstance(v, list):
        if not v:
            return C_MAGENTA + "[]" + C_RESET
        return C_MAGENTA + "[" + C_RESET + ",".join(c_value(x) for x in v) + C_MAGENTA + "]" + C_RESET
    return compact_json(v)


def c_path(path):
    s = c_ident("json")
    for p in path:
        if isinstance(p, int):
            s += f"[{p}]"
        else:
            if can_dot_identifier(p):
                s += "." + c_ident(p)
            else:
                s += "[" + C_YELLOW + quote_json_string(p) + C_RESET + "]"
    return s


def color_statement(st):
    return c_path(st.path) + " = " + c_value(st.value) + ";"


def color_json_line(v):
    return c_value(v)


def load_input(opts):
    arg = opts.args[0] if opts.args else "-"
    if arg == "-":
        try:
            data = sys.stdin.buffer.read()
        except Exception as e:
            eprint(str(e))
            raise SystemExit(2)
        return data.decode('utf-8', errors='replace'), None

    if arg.startswith('http://') or arg.startswith('https://'):
        try:
            headers = {'User-Agent': f'gron/{VERSION}', 'Accept': 'application/json', 'Accept-Encoding': 'gzip'}
            req = urllib.request.Request(arg, headers=headers)
            handlers = []
            if opts.proxy:
                handlers.append(urllib.request.ProxyHandler({'http': opts.proxy, 'https': opts.proxy}))
            if opts.insecure and arg.startswith('https://'):
                ctx = ssl._create_unverified_context()
                handlers.append(urllib.request.HTTPSHandler(context=ctx))
            opener = urllib.request.build_opener(*handlers) if handlers else urllib.request.build_opener()
            with opener.open(req) as resp:
                data = resp.read()
                if resp.headers.get('Content-Encoding', '').lower() == 'gzip':
                    data = gzip.decompress(data)
            return data.decode('utf-8', errors='replace'), None
        except Exception as e:
            # urllib's wording differs from Go's; keep the public error simple.
            eprint(str(e))
            raise SystemExit(4)

    if os.path.isdir(arg):
        return None, arg
    try:
        with open(arg, 'rb') as f:
            data = f.read()
        return data.decode('utf-8', errors='replace'), None
    except FileNotFoundError:
        eprint(f"open {arg}: no such file or directory")
        raise SystemExit(1)
    except PermissionError:
        eprint(f"open {arg}: permission denied")
        raise SystemExit(1)
    except OSError as e:
        # Most open failures are classified as open-file failures.
        eprint(f"open {arg}: {e.strerror.lower() if e.strerror else str(e)}")
        raise SystemExit(1)


def write_statements(statements, json_mode=False, color=False):
    for st in statements:
        if json_mode:
            line_obj = [st.path, st.value]
            line = color_json_line(line_obj) if color else compact_json(line_obj)
        else:
            line = color_statement(st) if color else st.line()
        sys.stdout.write(line + "\n")


def do_gron(opts, color):
    text, dir_path = load_input(opts)
    sort = not opts.no_sort
    if opts.stream:
        root = Statement([], [])
        write_statements([root], opts.json, color)
        if dir_path is not None:
            eprint(f"failed to form statements: read {dir_path}: is a directory")
            return 3
        idx = 0
        # Go's bufio.Scanner ScanLines does not emit a final empty token for a
        # trailing newline, but it does emit internal blank lines.
        for line in text.splitlines():
            try:
                val = decode_first_json(line)
            except ValueError as e:
                eprint(f"failed to form statements: {e}")
                return 3
            sts = form_statements(val, [idx], sort=sort)
            write_statements(sts, opts.json, color)
            idx += 1
        return 0

    if dir_path is not None:
        eprint(f"failed to form statements: read {dir_path}: is a directory")
        return 3
    try:
        val = decode_first_json(text)
    except ValueError as e:
        eprint(f"failed to form statements: {e}")
        return 3
    sts = form_statements(val, [], sort=sort)
    write_statements(sts, opts.json, color)
    return 0


def find_statement_end(line):
    in_str = False
    esc = False
    for i, ch in enumerate(line):
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
            elif ch == ';':
                return i
    return None


def extract_statement(line):
    if line == "" or line.strip(" \t\r\n") == "":
        return None, False
    # Leading whitespace is not accepted by the observed line parser; such
    # lines simply do not contribute statements.
    if line[0] in " \t":
        return None, False
    end = find_statement_end(line)
    if end is None:
        if '=' in line:
            return line.strip(' '), False
        if line[0] in '#/':
            return "", True
        return None, False
    return line[:end].strip(' '), True


class UngronParseError(Exception):
    def __init__(self, stmt, reason):
        self.stmt = stmt
        self.reason = reason
        super().__init__(reason)


class MergeError(Exception):
    pass


def parse_path(path_s):
    if path_s == "":
        return []
    path = []
    i = 0
    n = len(path_s)
    # Root token (possibly any identifier-ish run until a separator).
    if i < n and path_s[i] not in '.[':
        start = i
        while i < n and path_s[i] not in '.[':
            if path_s[i] in ' \t\r\n=':
                raise ValueError("invalid statement")
            i += 1
        if start != i:
            path.append(path_s[start:i])
    while i < n:
        ch = path_s[i]
        if ch == '.':
            i += 1
            start = i
            while i < n and path_s[i] not in '.[':
                if path_s[i] in ' \t\r\n=':
                    raise ValueError("invalid statement")
                i += 1
            if start == i:
                raise ValueError("invalid statement")
            path.append(path_s[start:i])
        elif ch == '[':
            i += 1
            if i < n and path_s[i] == '"':
                # Parse a JSON string and require a following ']'.
                dec = json.JSONDecoder()
                try:
                    val, end = dec.raw_decode(path_s, i)
                except json.JSONDecodeError:
                    raise ValueError("invalid statement")
                if not isinstance(val, str):
                    raise ValueError("invalid statement")
                i = end
                if i >= n or path_s[i] != ']':
                    raise ValueError("invalid statement")
                i += 1
                path.append(val)
            else:
                start = i
                while i < n and path_s[i].isdigit():
                    i += 1
                if start == i or i >= n or path_s[i] != ']':
                    bad = path_s[start:i] if start != i else path_s[start:start+1]
                    if bad:
                        raise ValueError(f"invalid integer key `{bad}`")
                    raise ValueError("invalid statement")
                idx = int(path_s[start:i], 10)
                i += 1
                path.append(idx)
        else:
            raise ValueError("invalid statement")
    return path


def parse_statement(stmt, had_semicolon=True):
    if stmt == "" or '=' not in stmt:
        raise UngronParseError(stmt, "invalid statement")
    if not had_semicolon:
        raise UngronParseError(stmt, "statement has no value")
    left, right = stmt.split('=', 1)
    path_s = left.strip(' ')
    value_s = right.strip(' ')
    if value_s == "":
        # Match the common diagnostic form.
        raise UngronParseError(f"{path_s} = ;", "invalid value ``")
    try:
        path = parse_path(path_s)
    except ValueError as e:
        raise UngronParseError(path_s, str(e))

    if value_s == "{}":
        return path, collections.OrderedDict()
    if value_s == "[]":
        return path, []
    if value_s.startswith('{'):
        raise UngronParseError(f"{path_s} = {{", "statement has no value")
    if value_s.startswith('['):
        raise UngronParseError(f"{path_s} = [", "statement has no value")

    dec = json.JSONDecoder(parse_int=lambda s: JsonNumber(s),
                           parse_float=lambda s: JsonNumber(s))
    try:
        val, end = dec.raw_decode(value_s)
        # Only spaces may trail inside the statement fragment.
        if value_s[end:].strip(' ') != "":
            raise json.JSONDecodeError("extra", value_s, end)
    except json.JSONDecodeError:
        raise UngronParseError(stmt, f"invalid value `{value_s}`")
    return path, val


def build_nested(path, value):
    cur = value
    for seg in reversed(path):
        if isinstance(seg, int):
            arr = [MISSING] * (seg + 1)
            arr[seg] = cur
            cur = arr
        else:
            d = collections.OrderedDict()
            d[seg] = cur
            cur = d
    return cur


def is_container(v):
    return isinstance(v, (dict, list))


def merge_values(old, new):
    if old is MISSING:
        return new
    if isinstance(old, dict):
        if not isinstance(new, dict):
            raise MergeError("cannot merge object with non-object")
        for k, nv in new.items():
            if k in old:
                old[k] = merge_values(old[k], nv)
            else:
                old[k] = nv
        return old
    if isinstance(old, list):
        if not isinstance(new, list):
            raise MergeError("cannot merge array with non-array")
        if len(old) < len(new):
            old.extend([MISSING] * (len(new) - len(old)))
        for i, nv in enumerate(new):
            if nv is MISSING:
                continue
            old[i] = merge_values(old[i], nv)
        return old
    # Old scalar.  A later scalar replaces it; a later container (a child
    # assignment) also replaces it, matching the observed forgiving direction.
    return new


def finalize_missing(v):
    if v is MISSING:
        return None
    if isinstance(v, list):
        return [finalize_missing(x) for x in v]
    if isinstance(v, dict):
        return collections.OrderedDict((k, finalize_missing(val)) for k, val in v.items())
    return v


def unwrap_json_root(v):
    if isinstance(v, dict) and len(v) == 1 and "json" in v:
        return v["json"]
    return v


def ungron_from_statements(lines):
    root = MISSING
    parsed = 0
    for line in lines:
        # Strip one trailing CR for CRLF input like bufio.Scanner.
        if line.endswith('\r'):
            line = line[:-1]
        stmt, had_semicolon = extract_statement(line)
        if stmt is None:
            continue
        path, val = parse_statement(stmt, had_semicolon)
        nested = build_nested(path, val)
        root = merge_values(root, nested)
        parsed += 1
    if parsed == 0:
        raise UngronParseError(None, "no statements were parsed")
    root = finalize_missing(root)
    root = unwrap_json_root(root)
    return root


def stringify_json_stream_path(path, val):
    # Error messages for JSON stream conversion use bracket notation for string
    # path components.
    s = "json"
    for p in path:
        if isinstance(p, str):
            s += "[" + quote_json_string(p) + "]"
        elif isinstance(p, int):
            s += f"[{p}]"
        else:
            s += f"[{p}]"
    return f"{s} = {compact_json(val)};"


def js_stream_loader(line):
    return json.loads(line,
                      object_pairs_hook=object_pairs_hook,
                      parse_int=lambda s: JSStreamNumber(s),
                      parse_float=lambda s: JSStreamNumber(s))


def convert_js_stream_value(v):
    if isinstance(v, JSStreamNumber):
        return JsonNumber(go_float_format_from_raw(v.raw))
    if isinstance(v, str) or v is None or v is True or v is False:
        return v
    if isinstance(v, list):
        if len(v) != 0:
            raise ValueError("invalid JSON layout")
        return []
    if isinstance(v, dict):
        if len(v) != 0:
            raise ValueError("invalid JSON layout")
        return collections.OrderedDict()
    return v


def path_component_from_js(x):
    if isinstance(x, str):
        return x
    if isinstance(x, JSStreamNumber):
        val = x.value
        if math.isfinite(val) and val == math.trunc(val):
            return int(val)
        # Return a marker string; caller formats the more specific error.
        raise ValueError(go_float_format_from_raw(x.raw))
    raise TypeError


def ungron_from_json_stream(text):
    root = MISSING
    parsed = 0
    # For empty input, json.Unmarshal on an empty line reports this rather than
    # "no statements".
    lines = text.splitlines()
    if not lines:
        raise ValueError("unexpected end of JSON input")
    for line in lines:
        try:
            row = js_stream_loader(line)
        except json.JSONDecodeError as e:
            raise ValueError(go_json_error(line, e))
        if not isinstance(row, list) or len(row) != 2 or not isinstance(row[0], list):
            raise ValueError("invalid JSON layout")
        rel_path = []
        for comp in row[0]:
            try:
                rel_path.append(path_component_from_js(comp))
            except TypeError:
                raise ValueError("invalid JSON layout")
            except ValueError as ve:
                # Non-integer numeric path component.
                bad = str(ve)
                stmt = stringify_json_stream_path(rel_path + [bad], convert_js_stream_value(row[1]) if not isinstance(row[1], (dict, list)) else row[1])
                raise UngronParseError(stmt, f"invalid integer key `{bad}`")
        try:
            val = convert_js_stream_value(row[1])
        except ValueError as ve:
            raise ValueError(str(ve))
        nested = build_nested(["json"] + rel_path, val)
        root = merge_values(root, nested)
        parsed += 1
    if parsed == 0:
        raise UngronParseError(None, "no statements were parsed")
    return unwrap_json_root(finalize_missing(root))


def do_ungron(opts, color):
    text, dir_path = load_input(opts)
    if dir_path is not None:
        # The exact original message varies by mode; this is close for public use.
        eprint(f"read {dir_path}: is a directory")
        return 5
    try:
        if opts.json:
            val = ungron_from_json_stream(text)
        else:
            val = ungron_from_statements(text.splitlines())
    except UngronParseError as e:
        if e.stmt is None and e.reason == "no statements were parsed":
            eprint(e.reason)
        else:
            eprint(f"ungron failed for `{e.stmt}`: {e.reason}")
        return 5
    except MergeError as e:
        eprint(f"failed to merge statements: {e}")
        return 5
    except ValueError as e:
        eprint(str(e))
        return 5
    if color:
        sys.stdout.write(color_json_line(val) + "\n")
    else:
        sys.stdout.write(pretty_json(val) + "\n")
    return 0


def parse_value_for_values(value_s):
    value_s = value_s.strip(' ')
    if value_s in ("{}", "[]") or value_s.startswith('{') or value_s.startswith('['):
        return None, False
    dec = json.JSONDecoder(parse_int=lambda s: JsonNumber(s),
                           parse_float=lambda s: JsonNumber(s))
    try:
        val, end = dec.raw_decode(value_s)
        if value_s[end:].strip(' ') != "":
            return None, False
    except Exception:
        return None, False
    if isinstance(val, (dict, list)):
        return None, False
    return val, True


def do_values(opts):
    text, dir_path = load_input(opts)
    if dir_path is not None:
        return 0
    for line in text.splitlines():
        stmt, had_semicolon = extract_statement(line[:-1] if line.endswith('\r') else line)
        if stmt is None or not had_semicolon or '=' not in stmt:
            continue
        _, right = stmt.split('=', 1)
        val, ok = parse_value_for_values(right)
        if not ok:
            continue
        if isinstance(val, str):
            sys.stdout.write(val + "\n")
        else:
            sys.stdout.write(compact_json(val) + "\n")
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        opts = parse_args(argv)
    except SystemExit as e:
        return int(e.code)
    if opts.help:
        sys.stderr.write(USAGE)
        return 0
    if opts.version:
        sys.stdout.write(f"gron version {VERSION}\n")
        return 0
    color = bool(opts.colorize) or (sys.stdout.isatty() and not opts.monochrome)
    if opts.values and not opts.ungron:
        try:
            return do_values(opts)
        except SystemExit as e:
            return int(e.code)
    if opts.ungron:
        try:
            return do_ungron(opts, color)
        except SystemExit as e:
            return int(e.code)
    try:
        return do_gron(opts, color)
    except SystemExit as e:
        return int(e.code)

if __name__ == '__main__':
    sys.exit(main())
